import { readFileSync, writeFileSync, mkdirSync, readdirSync, existsSync, statSync } from "node:fs";
import { resolve, dirname, basename } from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const repoRoot = resolve(__dirname, "..");
const skillsRoot = resolve(repoRoot, "lib/skills");
const distDir = resolve(repoRoot, "dist");
const outFile = resolve(distDir, "content-script.js");

const HEADER = `/*
 * Auto-generated by scripts/build-content-script.mjs.
 * Do not edit by hand. Run \`npm run build\` to regenerate.
 */`;

const WRAPPER_PREFIX = `(function installExtractor() {
  const MESSAGE_TYPE = "TYPEUI_EXTRACT_STYLES";

  if (window.__typeuiStyleExtractorInstalled) {
    return;
  }
  window.__typeuiStyleExtractorInstalled = true;

  const __extractors = {};
  function __TYPEUI_REGISTER_EXTRACTOR(id, fn) {
    if (typeof id !== "string" || typeof fn !== "function") return;
    __extractors[id] = fn;
  }

`;

const WRAPPER_SUFFIX = `
  function runEnabledExtractors(enabledIds) {
    const ids = Array.isArray(enabledIds) && enabledIds.length
      ? enabledIds
      : Object.keys(__extractors);
    const skills = {};
    const pendingFetches = [];
    for (const id of ids) {
      const fn = __extractors[id];
      if (typeof fn !== "function") continue;
      try {
        const result = fn(document, window);
        if (result && typeof result === "object") {
          if (Array.isArray(result.pendingFetches)) {
            for (const f of result.pendingFetches) {
              pendingFetches.push(Object.assign({ skill: id }, f));
            }
            const cloned = Object.assign({}, result);
            delete cloned.pendingFetches;
            skills[id] = cloned;
          } else {
            skills[id] = result;
          }
        }
      } catch (err) {
        skills[id] = { __error: err && err.message ? err.message : String(err) };
      }
    }
    return { skills, pendingFetches };
  }

  function buildMeta() {
    return {
      url: window.location.href,
      title: document.title || "Untitled page",
      hostname: window.location.hostname || "",
      pathname: window.location.pathname || "/",
      origin: window.location.origin || "",
      sampledAt: new Date().toISOString(),
      totalElements: document.querySelectorAll("*").length
    };
  }

  chrome.runtime.onMessage.addListener((message, _sender, sendResponse) => {
    if (!message || message.type !== MESSAGE_TYPE) {
      return;
    }
    try {
      const enabled = Array.isArray(message.enabledSkills) && message.enabledSkills.length
        ? message.enabledSkills
        : null;
      const { skills, pendingFetches } = runEnabledExtractors(enabled);
      sendResponse({
        ok: true,
        payload: {
          meta: buildMeta(),
          skills,
          pendingFetches
        }
      });
    } catch (error) {
      const text = error instanceof Error ? error.message : "Unknown extraction error";
      sendResponse({ ok: false, error: text });
    }
  });
})();
`;

function findExtractFiles() {
  if (!existsSync(skillsRoot)) {
    return [];
  }
  const dirs = readdirSync(skillsRoot)
    .filter((name) => statSync(resolve(skillsRoot, name)).isDirectory())
    .sort();

  const out = [];
  for (const skillDir of dirs) {
    const candidate = resolve(skillsRoot, skillDir, "extract.browser.js");
    if (existsSync(candidate)) {
      out.push({ skillId: skillDir, path: candidate });
    }
  }
  return out;
}

function readSource(file) {
  const raw = readFileSync(file.path, "utf8");
  return `// === skill: ${file.skillId} (${basename(file.path)}) ===\n${raw.trim()}\n// === end skill: ${file.skillId} ===\n`;
}

function build() {
  const files = findExtractFiles();
  const fragments = files.map(readSource).join("\n");
  const bundle = `${HEADER}\n${WRAPPER_PREFIX}${fragments}\n${WRAPPER_SUFFIX}`;

  if (!existsSync(distDir)) {
    mkdirSync(distDir, { recursive: true });
  }
  writeFileSync(outFile, bundle, "utf8");
  console.log(`[build] wrote ${outFile} (${bundle.length} bytes, ${files.length} skill extractors)`);
}

build();
